pub fn eh_palindromo(palavra: &str) -> bool {
    let chars: Vec<char> = palavra.chars().collect();
    let mut inicio = 0;
    let mut fim = chars.len().saturating_sub(1);

    while inicio < fim {
        if chars[inicio] != chars[fim] {
            return false;
        }
        inicio += 1;
        fim -= 1;
    }
    true
}

fn main() {
    println!("radar: {}", eh_palindromo("radar"));
    println!("rust: {}", eh_palindromo("rust"));
}
